import { MatrixHttpApi, type IHttpOpts } from "../http-api/index.ts";
import type { IKeyValueStore } from "../store/KeyValueStore.ts";
import { AuthManager } from "./auth/AuthManager.ts";
import { SyncManager, type SyncManagerOptions } from "./sync/SyncManager.ts";
import { CryptoManager } from "./crypto/CryptoManager.ts";
import { MessageProcessor } from "./messaging/MessageProcessor.ts";
import { RoomManager } from "./rooms/RoomManager.ts";
import { logger } from "../logger.ts";
import { TypedEventEmitter } from "../models/typed-event-emitter.ts";
import { type HttpApiEvent, type HttpApiEventHandlerMap } from "../http-api/interface.ts";

export interface MatrixClientOptions extends IHttpOpts {
    store: IKeyValueStore;
    syncOptions?: SyncManagerOptions;
}

export class MatrixClient {
    public readonly auth: AuthManager;
    public readonly sync: SyncManager;
    public readonly crypto: CryptoManager;
    public readonly messaging: MessageProcessor;
    public readonly rooms: RoomManager;
    public readonly http: MatrixHttpApi<IHttpOpts>;
    public readonly store: IKeyValueStore;

    public constructor(options: MatrixClientOptions) {
        const eventEmitter = new TypedEventEmitter<HttpApiEvent, HttpApiEventHandlerMap>();
        this.http = new MatrixHttpApi<IHttpOpts>(eventEmitter, options);
        this.store = options.store;

        this.auth = new AuthManager(this.http, this.store);
        this.sync = new SyncManager(this.http, this.store, options.syncOptions);
        this.crypto = new CryptoManager(this.http, this.store);
        this.messaging = new MessageProcessor(this.http);
        this.rooms = new RoomManager(this.http, this.store);

        logger.info("MatrixClient initialized");
    }

    public async start(): Promise<void> {
        if (!this.auth.isLoggedIn()) {
            throw new Error("Client is not logged in");
        }

        await this.sync.start();
        logger.info("MatrixClient started");
    }

    public async stop(): Promise<void> {
        await this.sync.stop();
        logger.info("MatrixClient stopped");
    }

    public async login(username: string, password: string): Promise<void> {
        await this.auth.loginWithPassword(username, password);
        logger.info(`Logged in as ${username}`);
    }

    public async logout(): Promise<void> {
        await this.auth.logout();
        await this.stop();
        logger.info("Logged out");
    }

    public async logoutAll(): Promise<void> {
        await this.auth.logoutAll();
        await this.stop();
        logger.info("Logged out from all sessions");
    }

    public getAccessToken(): string | null {
        return this.auth.getAccessToken();
    }

    public getUserId(): string | null {
        return this.auth.getUserId();
    }

    public isLoggedIn(): boolean {
        return this.auth.isLoggedIn();
    }

    public isSyncing(): boolean {
        return this.sync.isRunning();
    }

    public getSyncToken(): string | null {
        return this.sync.getSyncToken();
    }
}
